//! Rendering `packages/test-utils/src/fixtures.ts`.

use base64::prelude::*;
use miden_client::account::Account;
use miden_client::note::Note;
use miden_client::utils::Serializable;

/// Everything the generated file is written from.
pub struct Fixtures {
    /// The network the account and the note were deployed to, for the header.
    pub network_id: String,
    pub counter_contract: Account,
    pub counter_note: Note,
}

impl Fixtures {
    /// Renders the file.
    ///
    /// The layout is oxfmt's own — 2-space indent, 100-column width, double
    /// quotes — reproduced here so that a freshly generated file is already
    /// formatted: the `resource` blobs overflow the line and so sit on a
    /// continuation line, while the ids do not.
    pub fn render(&self) -> String {
        let account = &self.counter_contract;
        let note = &self.counter_note;
        let mut out = String::new();
        out.push_str(&format!(
            "// Generated by apps/api-compile/crates/generate-fixtures against {}.\n",
            self.network_id
        ));
        out.push_str("// Do not edit by hand — regenerate with `pnpm generate-fixtures`.\n\n");
        out.push_str(&format!(
            "export const COUNTER_CONTRACT_ID = \"{}\";\n",
            account.id().to_hex()
        ));
        out.push_str(&format!(
            "export const COUNTER_NOTE_ID = \"{}\";\n\n",
            note.id().to_hex()
        ));
        out.push_str("export const accounts = {\n");
        // `resource` is what `miden-verifier --resource-path` reads back with
        // `Account::read_from_bytes`, and `code` is the commitment
        // `miden-import` reports for the same account.
        out.push_str(&entry(
            "COUNTER_CONTRACT_ID",
            &BASE64_STANDARD.encode(account.to_bytes()),
            &account.code().commitment().to_hex(),
        ));
        out.push_str("};\n\nexport const notes = {\n");
        // The note equivalent, keyed on the note script's root.
        out.push_str(&entry(
            "COUNTER_NOTE_ID",
            &BASE64_STANDARD.encode(note.to_bytes()),
            &note.script().root().to_hex(),
        ));
        out.push_str("};\n");
        out
    }
}

/// One entry of the `accounts` or `notes` map.
fn entry(key: &str, resource: &str, code: &str) -> String {
    format!("  [{key}]: {{\n    resource:\n      \"{resource}\",\n    code: \"{code}\",\n  }},\n")
}
